import dsyrk = require( './index' );


// TESTS //

// The function returns a Float64Array...
{
	const A = new Float64Array( 25 );
	const C = new Float64Array( 25 );

	dsyrk( 'row-major', 'lower', 'no-transpose', 5, 5, 1.0, A, 5, 1.0, C, 5 ); // $ExpectType Float64Array
}

// The compiler throws an error if the function is provided a first argument which is not a string...
{
	const A = new Float64Array( 25 );
	const C = new Float64Array( 25 );

	dsyrk( 10, 'lower', 'no-transpose', 5, 5, 1.0, A, 5, 1.0, C, 5 ); // $ExpectError
	dsyrk( true, 'lower', 'no-transpose', 5, 5, 1.0, A, 5, 1.0, C, 5 ); // $ExpectError
	dsyrk( false, 'lower', 'no-transpose', 5, 5, 1.0, A, 5, 1.0, C, 5 ); // $ExpectError
	dsyrk( null, 'lower', 'no-transpose', 5, 5, 1.0, A, 5, 1.0, C, 5 ); // $ExpectError
	dsyrk( undefined, 'lower', 'no-transpose', 5, 5, 1.0, A, 5, 1.0, C, 5 ); // $ExpectError
	dsyrk( [], 'lower', 'no-transpose', 5, 5, 1.0, A, 5, 1.0, C, 5 ); // $ExpectError
	dsyrk( {}, 'lower', 'no-transpose', 5, 5, 1.0, A, 5, 1.0, C, 5 ); // $ExpectError
	dsyrk( ( A: number ): number => A, 'lower', 'no-transpose', 5, 5, 1.0, A, 5, 1.0, C, 5 ); // $ExpectError
}

